/* CommonJS entry point. Kept dependency-free so require('rupee-format') works everywhere on Node 18+. */
function assertFiniteNumber(value, name) { if (typeof value !== 'number' || !Number.isFinite(value)) throw new TypeError(`${name} must be a finite number.`); }
function assertRate(rate) { assertFiniteNumber(rate, 'GST rate'); if (rate < 0) throw new RangeError('GST rate cannot be negative.'); }
function round(value, decimals = 2) { const factor = 10 ** decimals; return Math.round((value + Number.EPSILON) * factor) / factor; }
function formatIndianNumber(value, options = {}) { assertFiniteNumber(value, 'Value'); const { minimumFractionDigits = 0, maximumFractionDigits = 2 } = options; return new Intl.NumberFormat('en-IN', { minimumFractionDigits, maximumFractionDigits }).format(value); }
function formatINR(value, options = {}) { assertFiniteNumber(value, 'Value'); const { minimumFractionDigits = 2, maximumFractionDigits = 2, currencyDisplay = 'symbol' } = options; return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', currencyDisplay, minimumFractionDigits, maximumFractionDigits }).format(value); }
const SMALL = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen']; const TENS = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
function underThousand(n) { const parts = []; if (n >= 100) { parts.push(`${SMALL[Math.floor(n / 100)]} Hundred`); n %= 100; } if (n >= 20) { parts.push(TENS[Math.floor(n / 10)]); if (n % 10) parts.push(SMALL[n % 10]); } else if (n) parts.push(SMALL[n]); return parts.join(' '); }
function numberToIndianWords(value) { assertFiniteNumber(value, 'Value'); if (!Number.isSafeInteger(value)) throw new RangeError('Value must be a safe integer.'); if (value === 0) return 'Zero'; const sign = value < 0 ? 'Minus ' : ''; let n = Math.abs(value); const parts = []; for (const [size, label] of [[10000000, 'Crore'], [100000, 'Lakh'], [1000, 'Thousand'], [1, '']]) { const group = Math.floor(n / size); if (group) { parts.push(underThousand(group) + (label ? ` ${label}` : '')); n %= size; } } return sign + parts.join(' '); }
function addGST(amount, rate) { assertFiniteNumber(amount, 'Amount'); assertRate(rate); const gstAmount = round(amount * rate / 100); return { taxableAmount: amount, gstRate: rate, gstAmount, totalAmount: round(amount + gstAmount) }; }
function removeGST(inclusiveAmount, rate) { assertFiniteNumber(inclusiveAmount, 'Inclusive amount'); assertRate(rate); const taxableAmount = round(inclusiveAmount / (1 + rate / 100)); return { taxableAmount, gstRate: rate, gstAmount: round(inclusiveAmount - taxableAmount), totalAmount: inclusiveAmount }; }
function splitGST(gstAmount, rate) { assertFiniteNumber(gstAmount, 'GST amount'); if (rate !== undefined) assertRate(rate); const cgstAmount = round(gstAmount / 2); const sgstAmount = round(gstAmount - cgstAmount); const result = { cgstAmount, sgstAmount }; if (rate !== undefined) Object.assign(result, { cgstRate: rate / 2, sgstRate: rate / 2 }); return result; }
function percentageOf(value, total) { assertFiniteNumber(value, 'Value'); assertFiniteNumber(total, 'Total'); if (total === 0) throw new RangeError('Total cannot be zero.'); return value / total * 100; }
function formatPercentage(value, options = {}) { assertFiniteNumber(value, 'Value'); const { minimumFractionDigits = 0, maximumFractionDigits = 2 } = options; return new Intl.NumberFormat('en-IN', { style: 'percent', minimumFractionDigits, maximumFractionDigits }).format(value / 100); }
module.exports = { formatIndianNumber, formatINR, numberToIndianWords, addGST, removeGST, splitGST, percentageOf, formatPercentage };
